		if BlockedTools[name] {
			return name
		}
	}
	return ""
}

func ToolAllowlisted(enabled []string, name string) bool {
	name = normalizeToolName(name)
	if name == "" {
		return false
	}
	if len(enabled) == 0 {
		return !BlockedTools[name]
	}
	for _, allowed := range enabled {
		if normalizeToolName(allowed) == name {
			return !BlockedTools[name]
		}
	}
	return false
}

